// === Tab: mySketch ===
let movers = [];
let attractor = [] ; 
let repulsion = []
let p
// let colorAtr = ["#ff5b4f","#b81a0f","#e64056"]

function setup() {
	createCanvas(1112, 834);
	background(232);
	pixelDensity(3)

	for(var i=0;i<10;i++){
		p = p5.Vector.random2D()
		p.setMag(random(140,450))	
		attractor[i] = new Attractor(width/2+p.x,height/2+p.y,random(30,80))
		attractor[i].show()
	}

	for(var o=0;o<20;o++){
		p = p5.Vector.random2D()
		p.setMag(random(240,550))	
		repulsion[o] = new Repulsion(width/2+p.x,height/2+p.y,random(50,105))
		repulsion[o].show()
	}


	for (let u = 0; u < 40; u++) {
    let x = width/2;
    let y = height/2;
    let m = random(1, 5);
    movers[u] = new Mover(x, y, m);
	}

}

function draw() {
	// background(232)

	for(let atr of attractor){
		for(let rep of repulsion){
			for(let mover of movers){
				atr.attract(mover)
				rep.repulsion(mover)
				mover.update()
				mover.show()
			}
		}
	}
}

// === Tab: Mover ===
class Mover{
	constructor(x,y,m){
		this.p = createVector(x,y)
		this.v = p5.Vector.random2D()
		this.v.mult(0.3)
		this.a = createVector(0,0)

		this.m = m
		this.r  = sqrt(this.m)*2
		this.ballR = this.r*10*random(0.6,1)

	}

	applyForce(force){
		let f = p5.Vector.div(force,this.m)
		this.a.add(f)
	}

	update(){
		this.v.add(this.a)

		this.p.add(this.v)
		this.v.limit(1)
		this.a.add(random(-8,8),random(-8,8))
		this.a.limit(0.045)
		this.ballR*=0.999

		this.a.set(0,0)
	}

	show(){
		noStroke()
		push()
			fill(0,25)
			translate(this.p.x,this.p.y)
			ellipse(0+random(-1,1),0+random(-1,1),this.ballR)
		pop()

		push()
			fill(45,180,90,random(15,25))
			translate(this.p.x,this.p.y)
			ellipse(0+random(-2,2),0+random(-2,2),this.ballR)
		pop()
	}
}

// === Tab: Attractor ===
//引力 F = m1*m2*G/||r||平方 * r方向 
class Attractor{
	constructor(x,y,m){
	this.p = createVector(x,y)
	this.m = m
	this.r = sqrt(this.m)*2
	this.c =  color(random(225,255), random(60,90), random(40,80),random(10,30))
	}


	attract(mover){
		let forceG = p5.Vector.sub(this.p,mover.p)
		let distanceSq = constrain(forceG.magSq(),100,200)
		let G = 0.064
		G*=0.85
		let strength =( (this.m*mover.m)*G)/distanceSq
		let dis = dist(mover.p.x,mover.p.y,this.p.x,this.p.y)
		forceG.setMag(strength)
		if(dis < this.r*9){
			mover.applyForce(forceG)
		}
		if(dis < this.r*3){
			forceG.mult(random(-3,-1.6))
			mover.applyForce(forceG)
		}
	}	


	show(){
		noStroke()
		fill(this.c)
		rectMode(CENTER)
		ellipse(this.p.x,this.p.y,this.r*10)

	}
}

// === Tab: Repulsion ===
class Repulsion{
	constructor(x,y,m){
	this.p = createVector(x,y)
	this.m = m
	this.r = sqrt(this.m)*2
	this.c =  color(0, random(60,90),random(225,255),random(10,30))
	}


	repulsion(mover){
		var forceG = p5.Vector.sub(this.p,mover.p)
		var distanceSq = constrain(forceG.magSq(),200,400)
		var G = -0.024
		G*=0.95
		var strength =( (this.m*mover.m)*G)/distanceSq
		var dis = dist(mover.p.x,mover.p.y,this.p.x,this.p.y)
		forceG.setMag(strength)
		if(dis < this.r*5){
			mover.applyForce(forceG)
		}
		if(dis < this.r*3){
			forceG.mult(random(-4,-1.6))
			mover.applyForce(forceG)
		}
	}	

	show(){
		noStroke()
		fill(this.c)
		rectMode(CENTER)
		ellipse(this.p.x,this.p.y,this.r*10)

	}
}

